"use client";

import { type CSSProperties, type ReactNode, useMemo } from "react";
import {
  Easing,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

export type SceneTransitionVariant =
  | "wipe"
  | "push"
  | "frosted"
  | "chromatic"
  | "pixelate";

export type SceneTransitionDirection = "up" | "down" | "left" | "right";

export type PixelatePattern = "wave" | "diagonal" | "spiral";

export interface SceneTransitionProps {
  /** Outgoing scene. Falls back to a light labeled panel. */
  from?: ReactNode;
  /** Incoming scene. Falls back to a dark labeled panel. */
  to?: ReactNode;
  /** Which transition to run between the two scenes. */
  variant?: SceneTransitionVariant;
  /** Travel direction of the transition (ignored by `pixelate`). */
  direction?: SceneTransitionDirection;
  /** Frame at which the transition begins. Defaults to 40% of the composition. */
  transitionStart?: number;
  /** Length of the transition window, in frames. */
  transitionDuration?: number;
  /** Backdrop blur of the sweeping glass pane (`frosted` only), in px. */
  glassBlur?: number;
  /** Peak RGB-split distance (`chromatic` only), in px. */
  aberrationOffset?: number;
  /** Mosaic columns (`pixelate` only). */
  cols?: number;
  /** Mosaic rows (`pixelate` only). */
  rows?: number;
  /** Dissolve order of the mosaic (`pixelate` only). */
  pattern?: PixelatePattern;
  /** Label of the fallback outgoing panel. */
  fromLabel?: string;
  /** Label of the fallback incoming panel. */
  toLabel?: string;
  /** Global playback multiplier. */
  speed?: number;
  className?: string;
}

const FONT_FAMILY =
  "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif";

/** Fast, subtle ease-out shared by the non-spring variants. */
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);

/** Frames a single mosaic cell takes to dissolve (`pixelate`). */
const CELL_FADE_FRAMES = 4;

function DefaultPanel({
  label,
  background,
  color,
}: {
  label: string;
  background: string;
  color: string;
}) {
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        background,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        color,
        fontFamily: FONT_FAMILY,
        fontSize: 88,
        fontWeight: 600,
        letterSpacing: "-0.02em",
      }}
    >
      {label}
    </div>
  );
}

/** Percentage offsets for the outgoing/incoming layers of a directional wipe. */
export function wipeOffsets(
  progress: number,
  direction: SceneTransitionDirection,
): { axis: "x" | "y"; fromOffset: number; toOffset: number } {
  const axis: "x" | "y" =
    direction === "left" || direction === "right" ? "x" : "y";
  const sign = direction === "left" || direction === "up" ? -1 : 1;
  return {
    axis,
    fromOffset: progress * 100 * sign,
    toOffset: (1 - progress) * 100 * -sign,
  };
}

/** Translate offset (%) of the sweeping glass pane along its axis. */
export function glassSweepOffset(
  progress: number,
  direction: SceneTransitionDirection,
): number {
  const reverse = direction === "left" || direction === "up";
  return reverse
    ? interpolate(progress, [0, 1], [110, -110])
    : interpolate(progress, [0, 1], [-110, 110]);
}

/** Smooth RGB-split strength: zero at both ends, peaking mid-transition. */
export function chromaticStrength(progress: number, offset: number): number {
  if (progress <= 0 || progress >= 1) return 0;
  return offset * Math.sin(Math.PI * progress);
}

/** Spiral traversal order of a cols x rows grid, outside-in. */
export function spiralIndices(cols: number, rows: number): number[][] {
  const grid: number[][] = Array.from({ length: rows }, () =>
    Array(cols).fill(0),
  );
  let top = 0;
  let bottom = rows - 1;
  let left = 0;
  let right = cols - 1;
  let i = 0;
  while (top <= bottom && left <= right) {
    for (let x = left; x <= right; x++) grid[top][x] = i++;
    top++;
    for (let y = top; y <= bottom; y++) grid[y][right] = i++;
    right--;
    if (top <= bottom) {
      for (let x = right; x >= left; x--) grid[bottom][x] = i++;
      bottom--;
    }
    if (left <= right) {
      for (let y = bottom; y >= top; y--) grid[y][left] = i++;
      left++;
    }
  }
  return grid;
}

/**
 * Per-cell dissolve delays (frames) for the pixelate mosaic, normalized so
 * every cell finishes fading within `transitionDuration`.
 */
export function pixelDelays(
  cols: number,
  rows: number,
  pattern: PixelatePattern,
  transitionDuration: number,
  cellFadeFrames: number = CELL_FADE_FRAMES,
): number[][] {
  const raw: number[][] = Array.from({ length: rows }, () =>
    Array(cols).fill(0),
  );
  const spiral = pattern === "spiral" ? spiralIndices(cols, rows) : null;
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      if (pattern === "wave") {
        raw[y][x] = Math.hypot(x - (cols - 1) / 2, y - (rows - 1) / 2);
      } else if (pattern === "diagonal") {
        raw[y][x] = x + y;
      } else if (spiral) {
        raw[y][x] = spiral[y][x];
      }
    }
  }

  let min = Infinity;
  let max = -Infinity;
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      if (raw[y][x] < min) min = raw[y][x];
      if (raw[y][x] > max) max = raw[y][x];
    }
  }

  const span = Math.max(0, transitionDuration - cellFadeFrames);
  const range = max - min || 1;
  return raw.map((row) => row.map((v) => ((v - min) / range) * span));
}

export function SceneTransition({
  from,
  to,
  variant = "wipe",
  direction = "up",
  transitionStart,
  transitionDuration = 14,
  glassBlur = 24,
  aberrationOffset = 8,
  cols = 12,
  rows = 7,
  pattern = "wave",
  fromLabel = "Before",
  toLabel = "After",
  speed = 1,
  className,
}: SceneTransitionProps) {
  const frame = useCurrentFrame() * speed;
  const { fps, durationInFrames } = useVideoConfig();

  const start =
    typeof transitionStart === "number"
      ? transitionStart
      : Math.floor(durationInFrames * 0.4);

  const progress = interpolate(
    frame,
    [start, start + transitionDuration],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: EASE_OUT,
    },
  );

  const delays = useMemo(
    () =>
      variant === "pixelate"
        ? pixelDelays(cols, rows, pattern, transitionDuration)
        : null,
    [variant, cols, rows, pattern, transitionDuration],
  );

  const fromContent = from ?? (
    <DefaultPanel label={fromLabel} background="#FAFAFA" color="#101828" />
  );
  const toContent = to ?? (
    <DefaultPanel label={toLabel} background="#0A0A0B" color="#FAFAFA" />
  );

  const container: CSSProperties = {
    position: "absolute",
    inset: 0,
    overflow: "hidden",
  };

  if (variant === "wipe" || variant === "chromatic") {
    const { axis, fromOffset, toOffset } = wipeOffsets(progress, direction);
    const transformFor = (offset: number) =>
      axis === "x" ? `translateX(${offset}%)` : `translateY(${offset}%)`;

    const split =
      variant === "chromatic"
        ? chromaticStrength(progress, aberrationOffset)
        : 0;
    const filter =
      split > 0.5
        ? axis === "x"
          ? `drop-shadow(-${split}px 0 0 rgba(255,0,0,0.8)) drop-shadow(${split}px 0 0 rgba(0,255,255,0.8))`
          : `drop-shadow(0 -${split}px 0 rgba(255,0,0,0.8)) drop-shadow(0 ${split}px 0 rgba(0,255,255,0.8))`
        : "none";

    return (
      <div className={className} style={{ ...container, filter }}>
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: transformFor(fromOffset),
            willChange: "transform",
          }}
        >
          {fromContent}
        </div>
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: transformFor(toOffset),
            willChange: "transform",
          }}
        >
          {toContent}
        </div>
      </div>
    );
  }

  if (variant === "push") {
    const outProgress = interpolate(
      frame,
      [start, start + transitionDuration],
      [0, 1],
      {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
        easing: EASE_OUT,
      },
    );
    const fromScale = interpolate(outProgress, [0, 1], [1, 0.94]);
    const fromBrightness = interpolate(outProgress, [0, 1], [1, 0.7]);
    const fromRadius = interpolate(outProgress, [0, 1], [0, 12]);

    // High-damping spring: settles fast, no bounce.
    const inSpring = spring({
      frame: frame - start,
      fps,
      config: { damping: 200 },
      durationInFrames: transitionDuration,
    });

    const toTransform =
      direction === "up"
        ? `translateY(${(1 - inSpring) * 100}%)`
        : direction === "down"
          ? `translateY(${(inSpring - 1) * 100}%)`
          : direction === "left"
            ? `translateX(${(1 - inSpring) * 100}%)`
            : `translateX(${(inSpring - 1) * 100}%)`;

    const toShadow =
      direction === "up"
        ? "0 -32px 80px rgba(16,24,40,0.35)"
        : direction === "down"
          ? "0 32px 80px rgba(16,24,40,0.35)"
          : direction === "left"
            ? "-32px 0 80px rgba(16,24,40,0.35)"
            : "32px 0 80px rgba(16,24,40,0.35)";

    return (
      <div className={className} style={container}>
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: `scale(${fromScale})`,
            filter: `brightness(${fromBrightness})`,
            borderRadius: `${fromRadius}px`,
            overflow: "hidden",
            willChange: "transform",
          }}
        >
          {fromContent}
        </div>
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: toTransform,
            boxShadow: toShadow,
            willChange: "transform",
          }}
        >
          {toContent}
        </div>
      </div>
    );
  }

  if (variant === "frosted") {
    const sweep = glassSweepOffset(progress, direction);
    const vertical = direction === "up" || direction === "down";
    const showTo = progress >= 0.5 ? 1 : 0;
    const hairline = "1px solid rgba(255,255,255,0.25)";

    return (
      <div className={className} style={container}>
        <div style={{ position: "absolute", inset: 0 }}>{fromContent}</div>
        <div style={{ position: "absolute", inset: 0, opacity: showTo }}>
          {toContent}
        </div>
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: vertical
              ? `translateY(${sweep}%)`
              : `translateX(${sweep}%)`,
            backdropFilter: `blur(${glassBlur}px)`,
            WebkitBackdropFilter: `blur(${glassBlur}px)`,
            background: "rgba(255,255,255,0.06)",
            borderLeft: vertical ? undefined : hairline,
            borderRight: vertical ? undefined : hairline,
            borderTop: vertical ? hairline : undefined,
            borderBottom: vertical ? hairline : undefined,
            willChange: "transform",
          }}
        />
      </div>
    );
  }

  // variant === "pixelate"
  const cells: ReactNode[] = [];
  if (delays) {
    for (let y = 0; y < rows; y++) {
      for (let x = 0; x < cols; x++) {
        const delay = delays[y][x];
        const opacity =
          frame < start
            ? 1
            : interpolate(
                frame,
                [start + delay, start + delay + CELL_FADE_FRAMES],
                [1, 0],
                { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
              );
        cells.push(
          <div key={`${x}-${y}`} style={{ background: "#0A0A0B", opacity }} />,
        );
      }
    }
  }

  return (
    <div className={className} style={container}>
      <div style={{ position: "absolute", inset: 0 }}>{toContent}</div>
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "grid",
          gridTemplateColumns: `repeat(${cols}, 1fr)`,
          gridTemplateRows: `repeat(${rows}, 1fr)`,
        }}
      >
        {cells}
      </div>
      <div
        style={{
          position: "absolute",
          inset: 0,
          opacity: frame < start ? 1 : 0,
        }}
      >
        {fromContent}
      </div>
    </div>
  );
}
